package com.crms.entity;import com.crms.enums.InterviewStatus;import java.time.Instant;import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.mapping.Document;@Document("interviews") public class Interview{@Id private Long id;private Application application;private Instant scheduledAt;private String mode,meetingLink,feedback;private InterviewStatus status=InterviewStatus.SCHEDULED;public Long getId(){return id;}public void setId(Long v){id=v;}public Application getApplication(){return application;}public void setApplication(Application v){application=v;}public Instant getScheduledAt(){return scheduledAt;}public void setScheduledAt(Instant v){scheduledAt=v;}public String getMode(){return mode;}public void setMode(String v){mode=v;}public String getMeetingLink(){return meetingLink;}public void setMeetingLink(String v){meetingLink=v;}public InterviewStatus getStatus(){return status;}public void setStatus(InterviewStatus v){status=v;}public String getFeedback(){return feedback;}public void setFeedback(String v){feedback=v;}}
